});

return $input.all().map((item) => {
    const p = item.json ?? {};
    const profile = p.profile ?? {};
    const analysis = p.analysis ?? {};

    const normalize = (value) =>
        String(value ?? "")
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9]/g, "");

    const clamp = (value, min = 0, max = 100) =>
        Math.min(max, Math.max(min, Number(value) || 0));

    const seniority = String(analysis.seniority ?? "");
    const decisionPower = String(analysis.decision_power ?? "");

    /*
     * Preserve relationship evidence from any known upstream location.
     */
    const relationshipEvidence =
        p.relationship_evidence ??
        analysis.relationship_evidence ??
        profile.relationship_evidence ??
        p.ai_analysis?.relationship_evidence ??
        null;

    /*
     * Use the actual target company when it exists.
     */
    const targetCompany =
        p.target_company ??
        p.target?.company ??
        p.target?.current_company ??
        "";

    const currentCompany = profile.current_company ?? "";

    const hasTargetCompany =
        normalize(targetCompany).length > 0;

    const companyMatch =
        hasTargetCompany &&
        normalize(currentCompany) === normalize(targetCompany);

    /*
     * Prefer an existing warm score.
     */
    const relationshipStrength = clamp(
        analysis.warm_score ??
        analysis.relationship_score ??
        p.warm_score ??
        0
    );

    const credibility =
        seniority === "Founder" ||
        seniority === "C-Level" ||
        seniority === "Executive"
            ? 95
            : seniority === "Lead" ||
              seniority === "Director" ||
              seniority === "Senior"
            ? 85
            : seniority === "Mid"
            ? 75
            : 60;

    const likelihood =
        decisionPower === "Very High"
            ? 90
            : decisionPower === "High"
            ? 80
            : decisionPower === "Medium"
            ? 65
            : 50;

    const companyAlignment = hasTargetCompany
        ? companyMatch
            ? 100
            : 40
        : 70;

    const introductionQuality = Math.round(
        (
            relationshipStrength +
            credibility +
            likelihood
        ) / 3
    );

    const recommendation =
        introductionQuality >= 85
            ? "Strong"
            : introductionQuality >= 70
            ? "Moderate"
            : "Weak";

    const companyReason = !hasTargetCompany
        ? "Target company was not provided; a neutral alignment score was used."
        : companyMatch
        ? "Currently works at the target company."
        : "Works outside the target company.";

    const targetCompanyLabel =
        targetCompany ||
        currentCompany ||
        "the target company";

    return {
        json: {
            ...p,

            /*
             * Keep the evidence available at the top level too,
             * so downstream nodes can access it easily.
             */
            relationship_evidence: relationshipEvidence,

            ai_analysis: {
                relationship_evidence: relationshipEvidence,

                relationship_strength: {
                    score: relationshipStrength,
                    level:
                        relationshipStrength >= 80
                            ? "Strong"
                            : relationshipStrength >= 60
                            ? "Medium"
                            : "Weak"
                },

                credibility: {
                    score: credibility,
                    level:
                        credibility >= 85
                            ? "High"
                            : credibility >= 70
                            ? "Medium"
                            : "Low"
                },

                company_alignment: {
                    score: companyAlignment,
                    reason: companyReason
                },

                industry_alignment: {
                    score: 80,
                    reason:
                        "Estimated from the detected role and experience."
                },

                likelihood_of_reply: {
                    score: likelihood,
                    reason:
                        "Estimated using seniority, decision power and profile quality."
                },

                introduction_quality: {
                    score: introductionQuality,
                    reason:
                        "Estimated from relationship strength, credibility and likelihood of reply."
                },

                overall_recommendation: recommendation,

                explanation:
                    "Temporary mock AI analysis generated from the rule-engine outputs.",

                personalized_introduction:
                    `Hi ${profile.name || "there"}, ` +
                    `I came across your profile while exploring professionals at ` +
                    `${targetCompanyLabel}. I was impressed by your background ` +
                    `and would love to connect and learn more about your experience.`
            }
        }
    };
});

return $input.all().map(item => {
    const p = item.json;

    const ruleScore = p.analysis?.warm_score || 0;

    const ai = p.ai_analysis;

    const relationship = ai.relationship_strength.score;
    const credibility = ai.credibility.score;
    const company = ai.company_alignment.score;
    const industry = ai.industry_alignment.score;
    const reply = ai.likelihood_of_reply.score;
    const intro = ai.introduction_quality.score;

    // Weighted final score
    const finalScore = Math.round(
        ruleScore * 0.30 +
        relationship * 0.15 +
        credibility * 0.15 +
        company * 0.15 +
        industry * 0.10 +
        reply * 0.10 +
        intro * 0.05
    );

    let finalGrade;

    if (finalScore >= 90)
        finalGrade = "A+";
    else if (finalScore >= 80)
        finalGrade = "A";
    else if (finalScore >= 70)
        finalGrade = "B";
    else if (finalScore >= 60)
        finalGrade = "C";
    else if (finalScore >= 50)
        finalGrade = "D";
    else
        finalGrade = "F";

    // ----------------------------
    // Why this candidate ranked highly
    // ----------------------------
    const highlights = [];

    if (relationship >= 80)
        highlights.push("Strong relationship potential");

    if (company >= 80)
        highlights.push("Excellent company alignment");

    if (industry >= 80)
        highlights.push("Relevant industry experience");

    if (credibility >= 80)
        highlights.push("High professional credibility");

    if (reply >= 80)
        highlights.push("High likelihood of responding");

    if (intro >= 80)
        highlights.push("Personalized introduction is highly relevant");

    if (ruleScore >= 80)
        highlights.push("Excellent warm-path score");

    if (p.analysis?.decision_power === "Very High")
        highlights.push("Very high decision-making influence");
    else if (p.analysis?.decision_power === "High")
        highlights.push("High decision-making influence");

    if (p.analysis?.hiring_influence === "Very High")
        highlights.push("Very high hiring influence");
    else if (p.analysis?.hiring_influence === "High")
        highlights.push("High hiring influence");

    const topCandidateReason = {
        title: "Why this candidate?",
        summary:
            `${p.name || "This candidate"} ranked among the top candidates because of a strong combination of relationship strength, company fit, credibility, and outreach potential.`,
        highlights: highlights.slice(0, 5)
    };

    return {
        json: {
            ...p,

            final_score: finalScore,
            final_grade: finalGrade,

            top_candidate_reason: topCandidateReason
        }
    };
});

const total = $input.all();

return total.map((item, index) => {
  const p = item.json ?? {};

  const profile = p.profile ?? {};
  const analysis = p.analysis ?? {};
  const aiAnalysis = p.ai_analysis ?? {};

  const targetCompany =
