      name: profile.name ?? "",
      linkedin: profile.linkedin_url ?? "",

      company: profile.current_company ?? "",
      position: profile.position ?? "",
      location: profile.location ?? "",

      role: analysis.role ?? "",
      seniority: analysis.seniority ?? "",
      decision_power: analysis.decision_power ?? "",
      hiring_influence: analysis.hiring_influence ?? "",
      warm_score: analysis.warm_score ?? 0,
      warm_grade: analysis.warm_grade ?? "",

      recommendation:
        aiAnalysis.overall_recommendation ?? "",

      relationship_strength:
        aiAnalysis.relationship_strength?.level ?? "",

      relationship_evidence: relationshipEvidence,
      top_candidate_reason: topCandidateReason,

      explanation:
        aiAnalysis.explanation ?? "",

      introduction:
        aiAnalysis.personalized_introduction ?? "",

      profile,
      analysis,
      ai_analysis: aiAnalysis
    }
  };
});

const input = $input.first().json;

// Ensure the summary contains the top_3 array
if (!Array.isArray(input.top_3)) {
	throw new Error("top_3 array not found.");
}

// Convert the array into separate n8n items
return input.top_3.map(candidate => ({
	json: candidate
}));

return $input.all().map((item) => {
    const p = item.json;
    const evidence = p.relationship_evidence ?? {};

    let warmScore = 0;
    const reasons = [];

    if (evidence.same_company === true) {
        warmScore += 35;
        reasons.push("Same company");
    }

    if (evidence.same_department === true) {
        warmScore += 20;
        reasons.push("Same department");
    }

    if (evidence.same_location === true) {
        warmScore += 10;
        reasons.push("Same location");
    }

    if (evidence.same_school === true) {
        warmScore += 15;
        reasons.push("Same school");
    }

    const yearsAtCompany = Number(evidence.years_at_company) || 0;

    if (yearsAtCompany >= 5) {
        warmScore += 15;
        reasons.push("Long company tenure");
    } else if (yearsAtCompany >= 2) {
        warmScore += 10;
        reasons.push("Established company tenure");
    } else if (yearsAtCompany > 0) {
        warmScore += 5;
        reasons.push("Current company tenure");
    }

    const mutualConnections = Number(p.mutual_connections) || 0;

    if (mutualConnections >= 10) {
        warmScore += 15;
        reasons.push("Many mutual connections");
    } else if (mutualConnections >= 5) {
        warmScore += 10;
        reasons.push("Several mutual connections");
    } else if (mutualConnections > 0) {
        warmScore += 5;
        reasons.push("Mutual connection");
    }

    warmScore = Math.min(100, warmScore);

    let warmGrade;

    if (warmScore >= 85) {
        warmGrade = "A";
    } else if (warmScore >= 70) {
        warmGrade = "B";
    } else if (warmScore >= 55) {
        warmGrade = "C";
    } else if (warmScore >= 40) {
        warmGrade = "D";
    } else {
        warmGrade = "F";
    }

    return {
        json: {
            ...p,
            warm_score: warmScore,
            warm_grade: warmGrade,
            warm_reasons: reasons
        }
    };
});

const rows = $input.all().map((item) => item.json ?? {});

/*
 * Merge2 receives:
 * - 28 full rows from ranked_candidates
 * - 3 simplified rows from top_candidates
 *
 * Only ranked_candidates rows contain the complete:
 * profile, analysis and ai_analysis objects.
 */
const rankedCandidates = rows.filter((row) => {
  const profile = row.profile ?? {};

  return Boolean(
    profile &&
    typeof profile === "object" &&
    profile.name &&
    profile.linkedin_url &&
    row.analysis &&
    typeof row.analysis === "object" &&
    row.ai_analysis &&
    typeof row.ai_analysis === "object"
  );
});

/*
 * Remove accidental duplicate ranked rows using LinkedIn URL.
 */
const uniqueRankedCandidates = Array.from(
  new Map(
    rankedCandidates.map((candidate) => [
      String(candidate.profile.linkedin_url).trim().toLowerCase(),
      candidate
    ])
  ).values()
);

const totalCandidates = uniqueRankedCandidates.length;

/*
 * Calculate average score only from the 28 valid ranked candidates.
 */
const scores = uniqueRankedCandidates
  .map((row) => Number(row.final_score ?? row.score))
  .filter((score) => Number.isFinite(score));

const averageFinalScore =
  scores.length > 0
    ? Math.round(
        scores.reduce((sum, score) => sum + score, 0) / scores.length
      )
    : 0;

/*
 * Try to recover the original target from the Webhook node.
 */
let webhookData = {};

try {
  webhookData = $("Webhook").first().json ?? {};
} catch (error) {
  webhookData = {};
}

const webhookTarget =
  webhookData.target ??
  webhookData.body?.target ??
  {};

/*
 * Also inspect candidate rows in case target information
 * was preserved somewhere downstream.
 */
const firstCandidate = uniqueRankedCandidates[0] ?? {};

const rowWithTarget = rows.find(
  (row) =>
    row.target ||
    row.target_person ||
    row.target_company
) ?? {};

const targetCompany =
  webhookTarget.current_company ||
  webhookTarget.company ||
  webhookTarget.target_company ||
  firstCandidate.target_company ||
  firstCandidate.target?.current_company ||
  firstCandidate.target?.company ||
  rowWithTarget.target_company ||
  rowWithTarget.target?.current_company ||
