      total_candidates: totalCandidates,
      top_candidates_count: Math.min(3, totalCandidates),
      average_final_score: averageFinalScore,

      completed_at: generatedAt,

      metadata: {
        generated_at: generatedAt,
        ranked_candidates_received: totalCandidates,
        top_candidates_received: Math.max(
          0,
          rows.length - rankedCandidates.length
        ),
        total_merged_items_received: rows.length
      }
    }
  }
